def _fd_snapshot():
    """The open descriptors of this process."""
    try:
        descriptor = os.open('/proc/self/fd', os.O_RDONLY)
    except OSError:
        return None
    try:
        names = os.listdir(descriptor)
    except OSError:
        return None
    finally:
        os.close(descriptor)
    return sorted(int(name) for name in names
                  if name.isdigit() and int(name) != descriptor)


