class Capture:
    """The collector of the outcome of every node of the scope."""

    def __init__(self):
        self.collected = []
        self.results = []

    def pytest_collection_finish(self, session):
        self.collected = [item.nodeid for item in session.items]
        if self.collected != EXPECTED_NODEIDS:
            import pytest
            pytest.exit('ROOT_FROZEN_NODE_SET_MISMATCH', returncode=4)

    def pytest_runtest_logreport(self, report):
        if report.when == 'call' or report.failed:
            self.results.append({'nodeid': report.nodeid, 'when': report.when,
                                 'outcome': report.outcome,
                                 'duration': round(report.duration, 6),
                                 'longrepr': str(report.longrepr) if report.failed else None})


